function primePalindrome(n) {
  if (n >= 8 && n <= 11) return 11;

  const isPrime = (x) => {
    if (x < 2) return false;
    if (x % 2 === 0) return x === 2;
    for (let d = 3; d * d <= x; d += 2) {
      if (x % d === 0) return false;
    }
    return true;
  };

  for (let root = 1; root < 100000; root++) {
    const half = String(root);
    const mirror = half.slice(0, -1).split('').reverse().join('');
    const candidate = Number(half + mirror);
    if (candidate >= n && isPrime(candidate)) {
      return candidate;
    }
  }
  return -1;
}

