function primePalindrome(n) {
  // Every palindrome of every length (even lengths included), in increasing order, tested by plain trial division.
  const prime = (x) => {
    if (x < 2) return false;
    for (let d = 2; d * d <= x; d++) if (x % d === 0) return false;
    return true;
  };
  for (let len = 1; len <= 9; len++) {
    const halfLen = Math.ceil(len / 2);
    const lo = halfLen === 1 ? 1 : 10 ** (halfLen - 1);
    for (let h = lo; h < 10 ** halfLen; h++) {
      const s = String(h);
      let tail = '';
      for (let i = len - halfLen - 1; i >= 0; i--) tail += s[i];
      const value = Number(s + tail);
      if (value >= n && prime(value)) return value;
    }
  }
  return -1;
}

