function generate(rand, size) {
  const r = rand();
  if (size === 'large') {
    // Mostly 8-digit inputs, which must jump over the gap to the first 9-digit answer.
    if (r < 0.6) return [10000000 + Math.floor(rand() * 90000001)];
    return [1000000 + Math.floor(rand() * 9000000)];
  }
  if (r < 0.4) return [1 + Math.floor(rand() * 200)];
  if (r < 0.7) {
    const k = 1 + Math.floor(rand() * 8);
    return [Math.min(100000000, Math.max(1, 10 ** k + Math.floor(rand() * 21) - 10))];
  }
  const digits = 1 + Math.floor(rand() * 8);
  return [Math.min(100000000, Math.max(1, Math.floor(10 ** (digits - 1 + rand()))))];
}
